// This file is generated by AI.

// 文档 Markdown 的 GFM 警告块 (GitHub Alert) 渲染:
//
// 后端 (webgal-language-service) 的文档由 `scripts/update-document.py` 从 VitePress 的
// `::: warning` 容器转成 GitHub 风格的 `> [!WARNING]`。标准 Markdown 没有这种语法, marked
// 只会把它当普通引用块, `[!WARNING]` 原样显示成一行文字 (没有标题, 也没有颜色)。
//
// 这里用第三方扩展 `marked-alert` 把 `> [!TYPE]` 识别成警告块, 渲染为
// `<div class="markdown-alert markdown-alert-{type}"><p class="markdown-alert-title">标题</p>…`。
//
// 类名随后被换成 data 属性: Monaco 渲染文档前会过一遍 HTML 消毒器
// (base/browser/markdownRenderer.js), 它只放行 **span** 上的 class, 其余元素的 class 一律
// 剥掉, 而 `data-*` 属性不受限制 —— 所以最终 DOM 是
// `<div data-alert="{type}"><p>标题</p>…`, 配色与标题样式在 styles.css 里给。
//
// 为什么要传入 marked 实例: 扩展必须注册到**真正渲染文档的那个实例**上。Monaco 渲染
// hover / 补全项的文档用的是它自己打包的 marked
// (monaco-editor/esm/vs/base/common/marked/marked.js), 与 npm 上的 `marked` 不是同一个实例,
// 注册到后者对 Monaco 无效 —— 所以这里不自己 import marked, 由调用方给实例
// (Ink 走 lsp/monaco.ts 的 Monaco 内部实例, 测试可以用 `new Marked()` 的独立实例)。

import alert, { type AlertVariantItem } from 'marked-alert';

/** marked 实例上用到的最小接口 (只需要 `use`), 便于把 Monaco 内部实例作为 any 传入。 */
export interface MarkedUseHost {
  use(...extensions: unknown[]): unknown;
}

/**
 * 警告块类型 -> 标题。
 *
 * 标题用中文: 文档与界面都是中文, 扩展默认的 `Note` / `Warning` 在这里显得突兀。
 * 图标留空: 扩展默认给的是 GitHub 的 SVG 图标, 而 Monaco 的消毒器只放行基础标签, SVG 会被
 * 剥掉 —— 不如不给, 类型由 styles.css 的配色区分。
 */
const VARIANTS: AlertVariantItem[] = [
  { type: 'note', icon: '', title: '注意' },
  { type: 'tip', icon: '', title: '提示' },
  { type: 'important', icon: '', title: '重要' },
  { type: 'warning', icon: '', title: '警告' },
  { type: 'caution', icon: '', title: '小心' },
];

/** 扩展产出的容器类名 -> 消毒器放行的 data 属性 (见文件头注释)。 */
const CONTAINER = /<div class="markdown-alert markdown-alert-([a-z-]+)">/g;
/** 标题类名同样会被剥掉, 这里一并去掉, 让标记与消毒后的 DOM 一致。 */
const TITLE = /<p class="markdown-alert-title">/g;

function rewriteAlertMarkup(html: string): string {
  return html.replace(CONTAINER, '<div data-alert="$1">').replace(TITLE, '<p>');
}

/**
 * 给 marked 实例注册 GitHub Alert 支持 (`> [!NOTE]` / `[!TIP]` / `[!IMPORTANT]` /
 * `[!WARNING]` / `[!CAUTION]`)。
 *
 * @param host 实际渲染文档的 marked 实例 (需要支持 `marked.use` 扩展)。
 */
export function installDocAlerts(host: MarkedUseHost): void {
  // `hooks.postprocess` 在整篇渲染完成后运行: 把警告块里注定会被消毒器剥掉的类名换成
  // data 属性 (见文件头注释), 其余标记不动。
  host.use(alert({ variants: VARIANTS }), { hooks: { postprocess: rewriteAlertMarkup } });
}
